import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))

	if len(inputs) == 0 {
		return out
	}

	if workers <= 0 {
		for i := range inputs {
			out[i] = fn(inputs[i])
		}
		return out
	}

	if workers > len(inputs) {
		workers = len(inputs)
	}

	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()

	return out
}

package cache

import "container/list"

type entry struct {
	key   string
	value int
}

type LRU struct {
	capacity int
	items    map[string]*list.Element
	list     *list.List
}

func NewLRU(capacity int) *LRU {
	if capacity < 0 {
		capacity = 0
	}

	return &LRU{
		capacity: capacity,
		items:    make(map[string]*list.Element),
		list:     list.New(),
	}
}

func (c *LRU) Get(key string) (int, bool) {
	elem, ok := c.items[key]
	if !ok {
		return 0, false
	}

	c.list.MoveToFront(elem)
	return elem.Value.(entry).value, true
}

func (c *LRU) Put(key string, value int) {
	if c.capacity == 0 {
		return
	}

	if elem, ok := c.items[key]; ok {
		c.list.MoveToFront(elem)
		elem.Value = entry{key: key, value: value}
		return
	}

	if c.list.Len() >= c.capacity {
		if back := c.list.Back(); back != nil {
			c.list.Remove(back)
			delete(c.items, back.Value.(entry).key)
		}
	}

	c.items[key] = c.list.PushFront(entry{key: key, value: value})
}

func (c *LRU) Len() int {
	return len(c.items)
}

export function groupConsecutive(values: number[]): number[][] {
  const groups: number[][] = [];

  for (const value of values) {
    const lastGroup = groups[groups.length - 1];

    if (lastGroup !== undefined && value - lastGroup[lastGroup.length - 1] === 1) {
      lastGroup.push(value);
    } else {
      groups.push([value]);
    }
  }

  return groups;
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

// Walks from a node to the root and returns the chain, root last.
// Uses async/await and a plain loop. Behaviour is unchanged,
// including that a cycle throws Error("cycle detected") and that the chain is
// capped at 50 entries with Error("chain too long").
export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let id: string = start;

  while (true) {
    if (seen.has(id)) throw new Error("cycle detected");
    seen.add(id);
    chain.push(id);
    if (chain.length > 50) throw new Error("chain too long");

    const node = await fetch(id);
    if (node.parent === null) return chain;
    id = node.parent;
  }
}

using System;
