using System.Linq;

public static class Ledger
{
    // Returns, for each account, the running balance after every entry, and the
    // final balance. Entries are (account, delta) in chronological order.
    public static (Dictionary<string, List<int>> Running, Dictionary<string, int> Final, double AverageDelta)
        Summarise(IEnumerable<(string Account, int Delta)> entries)
    {
        var totals = new Dictionary<string, int>();
        var running = new Dictionary<string, List<int>>();
        var deltas = new List<int>();

        foreach (var e in entries)
        {
            if (!totals.ContainsKey(e.Account))
            {
                totals[e.Account] = 0;
                running[e.Account] = new List<int>();
            }

            totals[e.Account] += e.Delta;
            running[e.Account].Add(totals[e.Account]);
            deltas.Add(e.Delta);
        }

        var average = deltas.Count == 0 ? 0.0 : (double)deltas.Sum() / deltas.Count();

        return (running, totals, average);
    }
}

using System.Collections.Generic;
using UnityEngine;

public class ProjectilePool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int prewarmCount;

    private readonly List<GameObject> pool = new List<GameObject>();

    private void Awake()
    {
        if (prefab == null)
        {
            return;
        }

        int count = Mathf.Max(0, prewarmCount);
        for (int i = 0; i < count; i++)
        {
            GameObject instance = Instantiate(prefab);
            instance.SetActive(false);
            pool.Add(instance);
        }
    }

    public GameObject Rent()
    {
        if (pool.Count > 0)
        {
            GameObject instance = pool[pool.Count - 1];
            pool.RemoveAt(pool.Count - 1);
            instance.SetActive(true);
            return instance;
        }

        if (prefab == null)
        {
            return null;
        }

        GameObject instance = Instantiate(prefab);
        instance.SetActive(true);
        return instance;
    }

    public void Return(GameObject go)
    {
        if (go == null)
        {
            return;
        }

        if (!IsInPool(go))
        {
            pool.Add(go);
        }

        go.SetActive(false);
    }

    private bool IsInPool(GameObject go)
    {
        for (int i = 0; i < pool.Count; i++)
        {
            if (pool[i] == go)
            {
                return true;
            }
        }

        return false;
    }
}

public class TelemetrySender
{
    private readonly NetworkManager _networkManager;

    public TelemetrySender(NetworkManager networkManager)
    {
        _networkManager = networkManager;
    }

    public void Send(string opcode, string payload)
    {
        if (opcode != null && opcode.Length > 8)
        {
            opcode = opcode.Substring(0, 8);
        }

        string frame = _networkManager.Encode(opcode, payload);
        _networkManager.Enqueue(frame);
    }
}

public static class FrameUtil
{
    public static int CountZeroes(FrameBuffer buffer)
    {
        int zeroes = 0;

        for (int i = 0; i < buffer.Count; i++)
        {
            if (buffer.Get(i) == 0)
            {
                zeroes++;
            }
        }

        return zeroes;
    }
}
